import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";import"./gzh-BO4QB3XE.js";import"./zsxq-BKcsYlFO.js";var i=JSON.parse(`{"path":"/column/Programmingthinking/17-How-to-calculate-PI-with-a-handful-of-rice.html","title":"18-怎样用一把大米计算圆周率？","lang":"zh-CN","frontmatter":{"title":"18-怎样用一把大米计算圆周率？","icon":"read","date":"2025-04-20T09:54:13.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1669634625000,"updatedTime":1745115089000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":9,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":3}],"changelog":[{"hash":"9ef45627c09b73df2f5434b00833541130d97a29","time":1745115089000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"up"},{"hash":"8d340cf97f9d808ed88661d5435cdd0d6d04a049","time":1745114131000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"init"},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"aed1739bbe0401281f8fe9b23c9bcb44b448b9ac","time":1743333691000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"启用编辑链接，提升文档的可用性和用户体验"},{"hash":"629179652779cb31e4b2f8cf498f512b7c970f95","time":1685451377000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"1"},{"hash":"d2f6408645561f94a1456e9fdbbcf5759ad6dcdd","time":1675746146000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"优化"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"610fee0943c20fde9f54fa74b604beca191c1a25","time":1674624916000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"remove password"},{"hash":"f08aaa80880a7b22af128caca0dba27069f28dfa","time":1672843073000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"修复文章日期"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":8.53,"words":2560},"filePathRelative":"column/Programmingthinking/17-How-to-calculate-PI-with-a-handful-of-rice.md"}`),a={name:`17-How-to-calculate-PI-with-a-handful-of-rice.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>你好，我是悦创。</p><p>你在小学六年级的数学课上，会学到一个数学符号叫做<strong>π</strong>，不是菠萝派的派啊，你可以点开文稿看看它的写法。其实，它表示的是“<strong>圆周率</strong>”。</p><figure><img src="data:image/jpeg;base64," alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>圆周率就是<strong>圆的周长跟直径的比值</strong>。你如果想要计算圆的周长或者面积，都要用到圆周率。但要想精确算出，圆周率到底是几，这可不容易。在古代，各国的数学家们在这个方面作出了很多努力。</p><p>在七年级历史课上，你会学到，咱们中国，在1500多年前有一位数学家叫<strong>祖冲之</strong>。他就算出圆周率小数点后边<strong>第7位数字</strong>。这是当时世界上最精确的圆周率了。而且，他的这个世界纪录还保持了<strong>800年</strong>，你说厉害不厉害？</p><figure><img src="/assets/6b83fc769e1086554d6fc45eb4538ffd-CHbIFaGG.jpg" alt="祖冲之  图片来源：三猎" tabindex="0" loading="lazy"><figcaption>祖冲之 图片来源：三猎</figcaption></figure><p>祖冲之计算圆周率的时候，使用的是一种叫“<strong>割圆法</strong>”的方法，这种方法很复杂，计算量非常大。所以，祖冲之能把结果算到小数点后边第七位，确实很不容易。</p><p>不过，时代在进步，后来，更巧妙的方法出现了。现在，我就要教给你用编程思维来计算圆周率。这样，你只需要<strong>一把大米</strong>，半天时间，就能算出π的值了。这种方法或许没有祖冲之的那么精确，可是真的特别快。</p><figure><img src="/assets/a802f8229e5ea3832f8b3030990beb9a-DfAU1SZH.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>这种编程思维，要先从面积计算说起。</p><p>你应该已经学过计算正方形、长方形、圆形的面积了吧？这些图形比较规则，只要知道了边长或者半径，套进公式，一下子就能算出来。</p><p>可是，你想过没有：不规则图形的面积该如何计算呢？比方说，你在“<strong>我的</strong>”这个栏目里可以找到自己领养的<strong>熊猫</strong>。它们看起来傻乎乎、圆滚滚的，还会喝奶啃竹子。那么，我问你：这只熊猫的面积是多少呢？</p><figure><img src="/assets/00c57cda3a6119e40c8f244f2b0a39e3-C7Fijo3A.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>诶，是不是有点挑战？这只熊猫的面积，<strong>没有现成的公式</strong>可套，算起来有点麻烦了！</p><p>那能不能把这只熊猫看成是由几个圆形<strong>组装起来</strong>的呢？你看，反正它脑袋圆圆的、身子圆圆的，就连手都是圆乎乎的，用几个圆来代替它，算出来的面积应该大差不差吧。</p><p>这也算是个好主意。不过，还有一种更好的方法，用它，你就能更快、更准确地算出熊猫的面积。什么方法呢？那就是撒大米。</p><p>你只要<strong>闭上眼睛</strong>，往手机屏幕上，撒下一层大米。这时候，只需要数出落在熊猫图案上的米粒数和整个屏幕上的米粒数，就能算出来熊猫的面积了。</p><p>是不是有点听蒙了？别着急，我再带你看一个更简单的情况。想象一下，如果一张纸上有两个圆圈，一大一小，我们闭上眼睛往纸上撒一把大米，肯定是撒到大圆圈里的比较多对吧？</p><p>假如大圆和小圆的<strong>面积之比</strong>是2:1，只要你撒的米粒足够多、足够均匀，那么这两个圆圈里米粒的<strong>数量</strong>也会是2:1，对吧。你看，这样我们就把图形的面积转化成米粒的数量了。</p><p>同样的，熊猫的面积也可以<strong>转化</strong>成米粒的数量。假如我们数出来，落在熊猫上的米粒，占整个屏幕上米粒的1/4，那么熊猫的面积，不就是整个屏幕的1/4吗？</p><p>手机屏幕的形状是规则的，我们只查一下手机厂商的官方数据，就可以知道面积了——这样一来熊猫的面积也就知道了。</p><p>当然了，你可能还会觉得一颗一颗数米粒太麻烦了。那还可以用咱们前面说的编程思维再做一次转换，不算米粒的数量，而是<strong>算重量</strong>。米粒越多当然就越重嘛。</p><p>你可以先称一称屏幕上全部米粒的重量，然后再称一次落在大熊猫图案上米粒的重量。两个重量一比较，也能算出大熊猫的面积来。</p><figure><img src="/assets/62b73878d27a66391f451288379dc105-Dwzh8APu.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>怎么样，很神奇吧！不需要使用公式，拿一把大米，就算出了熊猫的面积。你以后写作业的时候，是不是也可以随身带一包大米了呢？</p><p>哈哈，开个玩笑啊。这个数大米的方法，其实有个正式的名字，叫<strong>蒙特卡洛法</strong>。你一听这个名字，可能觉得，是不是有个叫蒙特卡洛的人，发明了这种伟大的方法。</p><p>其实不是的，这个蒙特卡洛呀，是欧洲的一座很小的<strong>城市</strong>，只有半个天安门广场那么大。它虽然小，却是<strong>世界三大赌城之一</strong>，是赌徒们爱去的地方。赌博不是什么好事，那为什么这个算法会起个赌城的名字呢？</p><figure><img src="/assets/70bff3058f9726598e3478191a2d4e5f-C733cQCo.jpg" alt="蒙特卡洛" tabindex="0" loading="lazy"><figcaption>蒙特卡洛</figcaption></figure><p>这事儿要追溯到20世纪40年代。当时啊，美国的一些科学家正忙着制造<strong>氢弹</strong>。在制造的过程中，科学家们遇到了一个很麻烦的问题，这个问题也没有什么现成的公式可以套用。怎么办呢？要是算不出这个题，氢弹就造不出来了，大家都很着急。</p><p>这时候，有一位叫<strong>乌拉姆</strong>的数学家想到一个好主意。当时，他正在打牌，突然就想，能不能算一下，自己拿到一手特殊的牌面的概率呢。如果要用公式来硬算，肯定会特别特别难。于是他就换了个思路，既然硬算算不出来，我不如用计算机模拟抓牌1万次，然后数一数其中有多少次拿到了这种特殊的牌面，不就行了吗？</p><figure><img src="/assets/85d472ffb350228f21fa9d6e7193715d-BrMVU-ZP.png" alt="乌拉姆" tabindex="0" loading="lazy"><figcaption>乌拉姆</figcaption></figure><p>你看啊，这个思路就跟前面我说的，用撒米的方法算面积是一样的，就是用<strong>模拟实验</strong>，来<strong>替代数学计算</strong>，求得结果。制造氢弹的那个计算，也可以使用这样的方法。</p><p>诶，这个主意很棒啊！于是，乌拉姆就赶紧跑过去跟另一位数学家<strong>冯·诺依曼</strong>说了他的灵感。冯·诺依曼是当时世界上计算机玩得最溜的人之一，美国第一台电子计算机能制造出来，就离不开冯·诺依曼的研究。</p><figure><img src="/assets/7b3e5563c44d0d88e8061658e8fc1b6f-Dzgu3-mF.png" alt="冯·诺依曼" tabindex="0" loading="lazy"><figcaption>冯·诺依曼</figcaption></figure><p>听到乌拉姆的建议，冯·诺依曼赶紧在计算机上编好了程序，问题果然解决了，<strong>氢弹也顺利制造出来了</strong>。</p><p>这个方法这么厉害，该起个什么名字呢？有一位数学家就说：干脆起名叫<strong>蒙特卡洛</strong>吧。这种方法本身就是<strong>受到牌局的启发</strong>而想出来的，它也会模拟各种各样的情况，乍一看跟翻来覆去投注赌博差不多。用蒙特卡洛这个赌城的名字来命名，多合适啊。</p><p>然后，它就真的叫这个名字了。听起来有点随便，也有些不光彩是不是呀？但那也没办法，现在大家都这么叫，改都没法改了。</p><p>不管怎样，咱们现在有了蒙特卡洛算法这么厉害的工具了，那它又是怎么计算π的值呢？</p><p>聪明的你可能已经想到了：在一张<strong>正方形</strong>的纸上画一个<strong>圆</strong>，圆的直径正好是正方形的边长。然后，闭上眼，撒大米！数出来圆里头的米粒，还有整张纸的米粒，就求出来了圆的面积。</p><figure><img src="data:image/jpeg;base64," alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>现在，有了圆的面积，也有了圆的直径，只需要<strong>做个除法</strong>，就能算出来π啦！你想想，古代人为了算出π值，不知道花了多少年呢！现在，咱们真的用一堆大米，就算出来了，这就是<strong>蒙特卡洛法</strong>的力量。</p><p>你看，蒙特卡洛算法不光能帮咱们解决数学上的π值，解出生活中不规则图案的面积，还可以帮科学家造出氢弹，是不是很有用？</p><p>听完这一讲，你也可以问问小伙伴：怎么撒一把大米来计算圆周率。如果他不知道的话，你就可以把这一讲分享给他听听啦！</p><p>下一讲，我还要给你说一种有用的算法思想，用这种思想，你就能做一道很厉害的菜：并行计算炒蛋！诶，这是什么黑暗料理呢？咱们下一集再说。</p><details class="hint-container details"><summary>公众号：AI悦创【二维码】</summary><figure><img src="/gzh.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure></details><div class="hint-container info"><p class="hint-container-title">AI悦创·编程一对一</p><p>AI悦创·推出辅导班啦，包括「Python 语言辅导班、C++ 辅导班、java 辅导班、算法/数据结构辅导班、少儿编程、pygame 游戏开发、Web、Linux」，招收学员面向国内外，国外占 80%。全部都是一对一教学：一对一辅导 + 一对一答疑 + 布置作业 + 项目实践等。当然，还有线下线上摄影课程、Photoshop、Premiere 一对一教学、QQ、微信在线，随时响应！微信：Jiabcdefh</p><p>C++ 信息奥赛题解，长期更新！长期招收一对一中小学信息奥赛集训，莆田、厦门地区有机会线下上门，其他地区线上。微信：Jiabcdefh</p><p>方法一：<a href="http://wpa.qq.com/msgrd?v=3&amp;uin=1432803776&amp;site=qq&amp;menu=yes" target="_blank" rel="noopener noreferrer">QQ</a></p><p>方法二：微信：Jiabcdefh</p></div><figure><img src="/zsxq.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure>`,47)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};